			return
		}
		if req.Role != "admin" && req.Role != "user" {
			req.Role = "user"
		}
		if req.Permissions == nil {
			req.Permissions = []string{}
		}

		var entry RBACEntry
		err = db.QueryRow(`
			INSERT INTO rbac (user_email, tenant_id, role, permissions, updated_at)
			VALUES ($1, $2, $3, $4, NOW())
