                            <>
                              <code
                                style={{
                                  fontSize: 10,
                                  fontFamily: '"SF Mono", monospace',
                                }}
                              >
                                {entry.workflow_id}
                              </code>
                              {entry.run_id && (
                                <span
                                  style={{
                                    color: "var(--fg-tertiary)",
                                    fontSize: 10,
                                  }}
                                >
                                  {" "}
                                  /{entry.run_id.substring(0, 8)}
                                </span>
                              )}
                            </>
                          ) : (
                            METRIC_LABELS[entry.metric_type] ||
                            entry.metric_type ||
                            "-"
                          )}
                        </span>
                      ) : (
                        <span>
                          {entry.alert_rule_id
                            ? `${METRIC_LABELS[entry.metric_type] || entry.metric_type} (threshold: ${entry.condition_type || ""} ${entry.threshold || ""})`
                            : METRIC_LABELS[entry.metric_type] ||
                              entry.metric_type ||
                              "-"}
                        </span>
                      )}
                    </td>
                    <td style={{ fontSize: 11, color: "var(--fg-secondary)" }}>
                      {entry.recipient || "-"}
                    </td>
                    <td>
                      <span
                        className={`alerts-history-status ${
                          entry.status === "sent" ||
                          entry.status === "delivered"
                            ? "history-status-sent"
                            : entry.status === "failed"
                              ? "history-status-failed"
                              : ""
                        }`}
                      >
                        {entry.status ?? "unknown"}
                      </span>
                      {entry.error_message && entry.error_message !== "" && (
                        <span
                          style={{
                            display: "block",
                            fontSize: 10,
                            color: "var(--danger)",
                            marginTop: 2,
                          }}
                        >
                          {entry.error_message}
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

