	now := time.Now()
	userSet := make(map[string]session)
	sessions.Range(func(k, v any) bool {
		s := v.(session)
		if now.After(s.Expiry) {
			sessions.Delete(k)
			return true
		}
		userSet[s.Email] = s
		return true
	})

	// Get RBAC entries for this tenant
