	rbacMap := make(map[string]RBACEntry)
	for rows.Next() {
		var e RBACEntry
		if err := rows.Scan(&e.ID, &e.UserEmail, &e.TenantID, &e.Role, &e.Persona, pq.Array(&e.Permissions), &e.CreatedAt, &e.UpdatedAt, &e.LastActivity); err != nil {
			log.Printf("ERROR: scan rbac: %v", err)
