		e.Persona = normalizeRBACPersona(e.Persona)
		rbacMap[e.UserEmail] = e
	}

	// Merge: all session users + any RBAC entries for users not currently signed in
	result := make([]map[string]interface{}, 0)
	seen := make(map[string]bool)

