    color: var(--danger-fg);
}

.wf-alert-timeout .wf-alert-title {
    color: var(--warning-fg);
}

.wf-alert-reason {
    margin: 0 0 4px;
    font-size: 13px;
    font-weight: 600;
    color: var(--fg);
}

.wf-alert-message {
    margin: 0;
    font-size: 12px;
    color: var(--fg-secondary);
}

.wf-modal-body {
    flex: 1;
    min-height: 0;
