    grid-template-columns: 1fr 380px;
    border-top: 1px solid var(--separator);
}

.wf-panel-label {
    margin: 0 0 12px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--fg-tertiary);
}

.wf-timeline-panel {
